CREATE TRIGGER chunk_document_delete AFTER DELETE ON chunks BEGIN
    DELETE FROM document_manifest WHERE chunk_id=OLD.chunk_id;
END

CREATE TRIGGER file_paths_fts_ad AFTER DELETE ON files BEGIN
    DELETE FROM file_paths_fts WHERE rowid = old.rowid;
END

CREATE TRIGGER file_paths_fts_ai AFTER INSERT ON files BEGIN
    INSERT INTO file_paths_fts(rowid, file_path) VALUES (new.rowid, new.file_path);
END

CREATE TRIGGER file_paths_fts_au AFTER UPDATE OF file_path ON files BEGIN
    DELETE FROM file_paths_fts WHERE rowid = old.rowid;
    INSERT INTO file_paths_fts(rowid, file_path) VALUES (new.rowid, new.file_path);
END

CREATE TRIGGER symbols_fts_ad AFTER DELETE ON symbols BEGIN
    DELETE FROM symbols_fts WHERE rowid = old.rowid;
END

CREATE TRIGGER symbols_fts_au AFTER UPDATE OF name ON symbols BEGIN
    DELETE FROM symbols_fts WHERE rowid = old.rowid;
    INSERT INTO symbols_fts(rowid, name, symbol_id, file_path)
    VALUES (new.rowid, new.name, new.symbol_id, new.file_path);
END
